import re
from pathlib import Path
dir = Path("supabase/migrations")
arquivos = sorted(p for p in dir.glob("*.sql"))
criadas = {}   # tabela -> arquivo que criou
colisoes = []
for p in arquivos:
    sql = p.read_text(encoding="utf8", errors="replace")
    for m in re.finditer(r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:public\.)?(\w+)\s*\(", sql, re.I):
        nome = m.group(1).lower()
        if nome in criadas:
            colisoes.append((nome, criadas[nome], p.name))
        else:
            criadas[nome] = p.name
    for m in re.finditer(r"CREATE\s+TYPE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:public\.)?(\w+)\s+AS\s+ENUM", sql, re.I):
        nome = "tipo:" + m.group(1).lower()
        if nome in criadas:
            colisoes.append((nome, criadas[nome], p.name))
        else:
            criadas[nome] = p.name
    for m in re.finditer(r"CREATE\s+(?:OR\s+REPLACE\s+)?FUNCTION\s+(?:public\.)?(\w+)\s*\(", sql, re.I):
        nome = "funcao:" + m.group(1).lower()
        criadas.setdefault(nome, p.name)
if colisoes:
    print("COLISOES:")
    for n, a, b in colisoes:
        print(f"  {n}\n    ja criada em: {a}\n    recriada em: {b}")
else:
    print("nenhuma colisao")
